"""Meridian CRM 4.2 EXPORT_ACCT fixed-width record formatter."""

from decimal import Decimal, ROUND_HALF_UP


def _value(row: dict, key: str) -> object:
    value = row.get(key, "")
    return "" if value is None else value


def _fixed(value: object, width: int) -> str:
    text = str(value)
    return text[:width].ljust(width)


def _integer_cents(value: object) -> int:
    if value == "":
        value = 0
    amount = Decimal(str(value))
    return int((amount * Decimal("100")).quantize(Decimal("1"), rounding=ROUND_HALF_UP))


def _zpad(value: object, width: int) -> str:
    return str(value).rjust(width, "0")


def format_account(row: dict) -> str:
    """Return the 77-character EXPORT_ACCT record for one ACCT_MASTER row."""
    acct_id = _fixed(_value(row, "ACCT_ID"), 10)
    acct_name = _fixed(_value(row, "ACCT_NM"), 40)
    region_code = _fixed(_value(row, "REGION_CD"), 3)
    annual_revenue = _zpad(_integer_cents(_value(row, "ANN_REV")), 15)

    credit_hold = _value(row, "CRED_HOLD")
    if credit_hold == "":
        credit_hold = "N"

    create_date = _value(row, "CREATE_DT")
    if create_date == "":
        create_date = "00000000"

    return acct_id + acct_name + region_code + annual_revenue + str(credit_hold) + str(create_date)
